```python
from itertools import permutations

def is_divisible_by_its_nonzero_digits(num):
    num_str = str(num)
    for digit in num_str:
        if digit == '0':
            return False
        if int(digit) == 0:
            continue
        if num % int(digit) != 0:
            return False
    return True

# Generate all permutations of 5 digits from 0 to 9 with the first digit not being 0
for perm in permutations(range(10), 5):
    if perm[0] != 0:
        num = int(''.join(map(str, perm)))
        if is_divisible_by_its_nonzero_digits(num):
            result = num
            break

print(result)
